"use server";

import { serverAction } from "rwsdk/worker";
import { drizzle } from "drizzle-orm/d1";
import { env } from "cloudflare:workers";
import { likes } from "@/db/schema";

export const incrementLikes = serverAction(async () => {
  const db = drizzle(env.DB);
  await db.insert(likes).values({});
});

"use client";

import { useTransition } from "react";
import { incrementLikes } from "../actions";

export const LikeButton = ({ count }: { count: number }) => {
  const [isPending, startTransition] = useTransition();

  const handleLike = () => {
    startTransition(async () => {
      await incrementLikes();
    });
  };

  return (
    <div style={{ fontFamily: "Noto Sans, sans-serif", padding: "2rem", textAlign: "center" }}>
      <h2>Persistent Like Button</h2>
      <div style={{ fontSize: "3rem", margin: "1rem 0" }}>
        Likes: <span data-testid="like-count">{count}</span>
      </div>
      <button
        data-testid="like-button"
        onClick={handleLike}
        disabled={isPending}
        style={{
          fontSize: "1.5rem",
          padding: "0.5rem 1.5rem",
          cursor: "pointer",
          borderRadius: "8px",
          border: "1px solid #ccc",
          backgroundColor: isPending ? "#eee" : "#0070f3",
          color: isPending ? "#666" : "#fff",
        }}
      >
        {isPending ? "Liking..." : "Like"}
      </button>
    </div>
  );
};

import { drizzle } from "drizzle-orm/d1";
import { env } from "cloudflare:workers";
import { likes } from "@/db/schema";
import { count } from "drizzle-orm";
import { LikeButton } from "./like-button";

export const Home = async () => {
  const db = drizzle(env.DB);
  const result = await db.select({ value: count() }).from(likes);
  const currentLikes = result[0]?.value ?? 0;

  return <LikeButton count={currentLikes} />;
};
